package challenge.leetcode.hard.rearrangingFruits;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * @author Administrator
 * @Created 02/08/2025,
 * @Project 3C: Competitive Coding Challenges
 * @Problem 2561
 * @Name Rearranging Fruits
 * @Difficulty Hard
 * @Tags array
 * arrays
 * hash table
 * greedy
 * sort
 * weekly contest 331
 * @link <a href="https://leetcode.com/problems/rearranging-fruits/">www.leetcode.com/2561</a>
 * @Description <p>You have two fruit baskets containing <code>n</code> fruits each.
 * You are given two <b>0-indexed</b> integer arrays <code>basket1</code> and <code>basket2</code>
 * representing the cost of fruit in each basket.
 * You want to make both baskets <b>equal</b>.
 * To do so, you can use the following operation as many times as you want:</p>
 *
 * <ul>
 * 		<li>Chose two indices <code>i</code> and <code>j</code>,
 * 			and swap the <code>i<sup>th</sup> </code>fruit of <code>basket1</code>
 * 			with the <code>j<sup>th</sup></code> fruit of <code>basket2</code>.</li>
 * 		<li>The cost of the swap is <code>min(basket1[i],basket2[j])</code>.</li>
 * </ul>
 *
 * <p>
 *     Two baskets are considered equal if sorting them according to the fruit cost makes them exactly the same baskets.
 * </p>
 *
 * <p>
 *     Return <i>the minimum cost to make both the baskets equal or</i> <code>-1</code><i> if impossible.</i>
 * </p>
 *
 * <ul>
 * 		<li><b>Example 1:</b>
 * 			<br><b>Input:</b> <code>basket1 = [4,2,2,2], basket2 = [1,4,1,2]</code>
 * 			<br><b>Output:</b> {@code 1}
 * 			<br><b>Explanation:</b> Swap index 1 of basket1 with index 0 of basket2, which has cost 1.
 * 				Now basket1 = [4,1,2,2] and basket2 = [2,4,1,2]. Rearranging both the arrays makes them equal.
 * 			<br>&emsp;- [3]
 * 			<br>&emsp;- [3,1]
 * 		</li>
 * </ul>
 * <ul>
 * 		<li><b>Example 2:</b>
 * 			<br><b>Input:</b> <code>basket1 = [2,3,4,1], basket2 = [3,2,5,1]</code>
 * 			<br><b>Output:</b> {@code -1}
 * 			<br><b>Explanation:</b> It can be shown that it is impossible to make both the baskets equal.
 * 		</li>
 * </ul>
 *
 * <br>
 * <p><b>Constraints:</b></p>
 *
 * <ul>
 * 		<li><code>basket1.length == basket2.length</code></li>
 * 		<li><code>1 &lt;= basket1.length &lt;= 10<sup>5</sup></code></li>
 * 		<li><code>1 &lt;= basket1[i],basket2[i] &lt;= 10<sup>9</sup></code></li>
 * </ul>
 **/
public class RearrangingFruits
{
	/**
	 * Solution scratch
	 * <br>
	 * <img src="data:image/jpeg;base64,"/>
	 */
	public static long minCost(int[] basketA, int[] basketB)
	{
		int min = basketA[0];
		long cost = 0;
		List<Long> excess = new ArrayList<>();
		Map<Integer, Integer> mapA = new HashMap<>();
		Map<Integer, Integer> mapB = new HashMap<>();
		Map<Integer, Integer> total = new HashMap<>();
		Map<Integer, Integer> freqA;

		for (int i = 0; i < basketA.length; i++)
		{
			min = Math.min(min, Math.min(basketA[i], basketB[i]));
			mapA.put(basketA[i], mapA.getOrDefault(basketA[i], 0) + 1);
			mapB.put(basketB[i], mapB.getOrDefault(basketB[i], 0) + 1);
			total.put(basketA[i], total.getOrDefault(basketA[i], 0) + 1);
			total.put(basketB[i], total.getOrDefault(basketB[i], 0) + 1);
		}
		freqA = new HashMap<>(mapA);

		// All elements must come in pairs
		// Because both arrays have equal size
		// and for them to have equal value whilst keeping equal sizes
		// means every number in one set, must be available in the other
		// otherwise, equality is not possible, so return -1
		for (Map.Entry<Integer, Integer> entry : total.entrySet())
		{
			if (entry.getValue() % 2 == 1)
			{
				return -1;
			}
		}

		// Map excess elements in A
		// new values assigned to keys are how many
		// that should be transferred over to basket B
		for (Map.Entry<Integer, Integer> entry : mapA.entrySet())
		{
			int b = mapB.getOrDefault(entry.getKey(), 0);
			int diff = (Math.max(entry.getValue() - b, 0)) / 2;
			mapA.put(entry.getKey(), diff);
			mapB.put(entry.getKey(), Math.max(b - diff, 0));
		}
		// Map excess elements in B
		// new values assigned to keys are how many
		// that should be transferred over to basket A
		for (Map.Entry<Integer, Integer> entry : mapB.entrySet())
		{
			int a = mapA.getOrDefault(entry.getKey(), 0);
			int diff = (Math.max(entry.getValue() - a, 0)) / 2;
			mapB.put(entry.getKey(), diff);
			mapA.put(entry.getKey(), Math.max(a - diff, 0));
		}

		for (Map.Entry<Integer, Integer> entry : total.entrySet())
		{
			int c = Math.abs(freqA.getOrDefault(entry.getKey(), 0) - entry.getValue() / 2);
			for (int i = 0; i < c; i++)
			{
				excess.add((long) entry.getKey());
			}
		}

		Collections.sort(excess);
		int swaps = excess.size() / 2;
		for (int i = 0; i < excess.size() / 2; i++)
		{
			cost += Math.min(excess.get(i), min * 2L);
		}

		return cost;
	}

	public static void swap(int[] basketA, int indexA, int[] basketB, int indexB)
	{
		int t = basketA[indexA];
		basketA[indexA] = basketB[indexB];
		basketB[indexB] = t;
		Arrays.sort(basketA);
		Arrays.sort(basketB);
	}

	/**
	 * Binary search of integer array
	 *
	 * @param ints
	 * @param value
	 * @return returns the search value
	 * or
	 * if the value is not found
	 * returns the CLOSEST value
	 * where it could be less than
	 * or
	 * more than the search value
	 */
	public static int search(int[] ints, int value)
	{
		int l = 0;
		int r = ints.length - 1;
		int m = r / 2;
		while (r - l > 2)
		{
			if (ints[m] == value)
			{
				return ints[m];
			}
			if (ints[m] > value)
			{
				r = m;
				m = r / 2;
			}
			else
			{
				l = m;
				m = l + (r - l) / 2;
			}
		}
		return ints[m] < value ? ints[r] : ints[l];
	}
}
